// `kubectl explain` for the kinds kube-lite serves — the documentation-ladder
// source for fields (05 §7.1). The descriptions are condensed from the
// Kubernetes v1.37 OpenAPI schema (kubernetes/kubernetes, Apache-2.0); the
// output layout is that of kubectl explain (GROUP/KIND/VERSION, FIELD,
// DESCRIPTION, FIELDS with types and -required-). Every field path also
// becomes a page `explain/<kind>.<path>` of the offline corpus.

import type { DocPage } from '../../../core/types';

export interface Field {
  /** Type as kubectl prints it: <string>, <integer>, <[]Container>, <map[string]string>, <Object>. */
  t: string;
  d: string;
  req?: boolean;
  /** Sub-fields, or the name of a shared definition. */
  f?: Record<string, Field> | string;
  /** Enum values printed in the description. */
  enum?: string[];
}

const s = (d: string, req = false): Field => ({ t: 'string', d, req });
const i = (d: string, req = false): Field => ({ t: 'integer', d, req });
const b = (d: string): Field => ({ t: 'boolean', d });
const ref = (t: string, d: string, def: string, req = false): Field => ({ t, d, f: def, req });
const map = (d: string): Field => ({ t: 'map[string]string', d });
const ios = (d: string, req = false): Field => ({ t: 'IntOrString', d, req });

