const meta = ref('ObjectMeta', "Standard object's metadata. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#metadata", 'ObjectMeta');
const top = (kindDesc: string, extra: Record<string, Field>): { d: string; f: Record<string, Field> } => ({
  d: kindDesc,
  f: {
    apiVersion: s('APIVersion defines the versioned schema of this representation of an object. Servers should convert recognized schemas to the latest internal value, and may reject unrecognized values.'),
    kind: s('Kind is a string value representing the REST resource this object represents. Servers may infer this from the endpoint the client submits requests to. Cannot be updated. In CamelCase.'),
    metadata: meta,
    ...extra,
  },
});

