function resolveFields(f: Field): Record<string, Field> | undefined {
  if (!f.f) return undefined;
  return typeof f.f === 'string' ? DEFS[f.f] : f.f;
}

function wrap(text: string, width = 76, indent = '    '): string {
  const words = text.split(/\s+/);
  const lines: string[] = [];
  let cur = '';
  for (const w of words) {
    if ((cur + ' ' + w).trim().length > width) {
      lines.push(cur);
      cur = w;
    } else cur = (cur + ' ' + w).trim();
  }
  if (cur) lines.push(cur);
  return lines.map((l) => indent + l).join('\n');
}

export interface ExplainTarget {
  kind: string;
  group: string;
  version: string;
  path: string[];
  field?: Field;
  fields?: Record<string, Field>;
  desc: string;
}

/** Walk "deployment.spec.strategy" to the field. */
export function findField(kind: string, path: string[]): ExplainTarget | { error: string } {
  const k = KINDS[kind];
  if (!k) return { error: `error: couldn't find resource for "${kind}"` };
  let fields: Record<string, Field> | undefined = k.f;
  let field: Field | undefined;
  for (const [n, part] of path.entries()) {
    const next: Field | undefined = fields?.[part];
    if (!next) return { error: `error: field "${part}" does not exist` + (n ? '' : '') };
    field = next;
    fields = resolveFields(next);
  }
  return { kind, group: k.group, version: k.version, path, field, fields: field ? fields : k.f, desc: field ? field.d : k.d };
}

/** The text `kubectl explain` prints. */
export function explainText(t: ExplainTarget, recursive = false): string {
  let out = '';
  if (t.group) out += `GROUP:      ${t.group}\n`;
  out += `KIND:       ${t.kind}\nVERSION:    ${t.version}\n\n`;
  if (t.field) out += `FIELD: ${t.path[t.path.length - 1]} <${t.field.t}>\n\n`;
  out += `DESCRIPTION:\n${wrap(t.desc)}\n`;
  if (t.field?.enum) out += `    \n    Possible enum values:\n${t.field.enum.map((e) => `     - \`${e}\``).join('\n')}\n`;
  out += '    \n';
  if (t.fields) {
    out += t.field ? 'FIELDS:\n' : 'FIELDS:\n';
    if (recursive) {
      const walk = (fs: Record<string, Field>, depth: number, seen: string[]) => {
        for (const [n, f] of Object.entries(fs).sort(([a], [b]) => a.localeCompare(b))) {
          out += `${'  '.repeat(depth + 1)}${n}\t<${f.t}>${f.req ? ' -required-' : ''}\n`;
          const sub = resolveFields(f);
          const key = typeof f.f === 'string' ? f.f : '';
          if (sub && depth < 6 && !seen.includes(key)) walk(sub, depth + 1, key ? [...seen, key] : seen);
        }
      };
      walk(t.fields, 0, []);
    } else {
      for (const [n, f] of Object.entries(t.fields).sort(([a], [b]) => a.localeCompare(b))) {
        out += `  ${n}\t<${f.t}>${f.req ? ' -required-' : ''}\n${wrap(f.d)}\n\n`;
      }
    }
  }
  return out.replace(/\n+$/, '\n');
}

/** Corpus pages for the documentation ladder: explain/<kind> and explain/<kind>.<path>, three levels deep. */
export function explainPages(): DocPage[] {
  const pages: DocPage[] = [];
  const add = (kind: string, path: string[]) => {
    const t = findField(kind, path);
    if ('error' in t) return;
    const id = `explain/${[kind.toLowerCase(), ...path].join('.')}`;
    const fieldsBody = t.fields
      ? Object.entries(t.fields)
          .sort(([a], [b]) => a.localeCompare(b))
          .map(([n, f]) => `${n} <${f.t}>${f.req ? ' -required-' : ''}\n  ${f.d}`)
          .join('\n\n')
      : '';
    const sections = [
      { id: 'KIND', title: 'KIND', body: `${t.group ? `GROUP: ${t.group}\n` : ''}KIND: ${t.kind}\nVERSION: ${t.version}${t.field ? `\nFIELD: ${path[path.length - 1]} <${t.field.t}>` : ''}` },
      { id: 'DESCRIPTION', title: 'DESCRIPTION', body: t.desc + (t.field?.enum ? `\n\nPossible enum values:\n${t.field.enum.map((e) => ` - ${e}`).join('\n')}` : '') },
      ...(fieldsBody ? [{ id: 'FIELDS', title: 'FIELDS', body: fieldsBody }] : []),
    ];
    pages.push({ id, source: 'kubectl-explain', title: `kubectl explain ${[kind.toLowerCase(), ...path].join('.')}`, url: 'https://kubernetes.io/docs/reference/kubernetes-api/', license: 'Apache-2.0 (Kubernetes OpenAPI descriptions)', version: 'v1.37', sections });
    if (path.length >= 3 || !t.fields) return;
    for (const n of Object.keys(t.fields)) {
      if (path.length === 0 && (n === 'apiVersion' || n === 'kind')) continue;
      add(kind, [...path, n]);
    }
  };
  for (const kind of Object.keys(KINDS)) add(kind, []);
  return pages;
}
